/* Signature Maithili Names Database — name-meaning lookup demo (jahdb-demo-1.0)
 * RUN ON PC: save as demo.js, then run:  node demo.js [name]
 * RUN IN BROWSER: paste into the console and press Enter. */
var TABLE = {"Ramjanki": "From Ram + Janki.", "Sitamadhav": "From Sita + Madhav.", "Mohanjanki": "From Mohan + Janki.", "Gitajanki": "From Gita + Janki.", "Jankimohan": "From Janki + Mohan.", "Madhavsita": "From Madhav + Sita.", "Ramjankijha": "Signature surname blending Ram-Janki + Jha.", "Sitamishra": "Signature surname.", "Mohanthakur": "Signature surname.", "Jankichoudhary": "Signature surname."};
function lookup(q){
  q=String(q||'').toLowerCase().trim();
  var keys=Object.keys(TABLE);
  for(var i=0;i<keys.length;i++){ if(keys[i].toLowerCase()===q) return keys[i]+' — '+TABLE[keys[i]]; }
  var hits=keys.filter(function(k){return k.toLowerCase().indexOf(q)>=0;});
  if(!hits.length) return 'No match for "'+q+'". Try: '+keys.slice(0,5).join(', ');
  return hits.map(function(k){return k+' — '+TABLE[k];}).join('\n');
}
var q=(typeof process!=='undefined'&&process.argv[2])||'Ramjanki';
console.log(lookup(q));

